def prune_tool_results(messages, keep_recent=3):
    """把最近 keep_recent 条之前的工具输出替换为占位摘要"""
    tool_idx = [i for i, m in enumerate(messages)
                if m["role"] == "tool"]
    for i in tool_idx[:-keep_recent]:
        messages[i]["content"] = (
            "[已裁剪] 原始工具输出已归档,"
            "关键结论: ... (摘要见归档文件)"
        )
    return messages
